const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0, 40.7]).buffer(20000); // 20km buffer around NYC
  const date = '2023-08-09';

  // NYC is EDT (UTC-4) in August
  // 2-3pm local = 18-19 UTC
  // 5-6pm local = 21-22 UTC

  // 2. Data Acquisition
  const no2Col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(date, '2023-08-10')
    .filterBounds(nyc)
    .select('tropospheric_NO2_column_number_density');

  const totalImages = no2Col.size().getInfo();
  console.log(`Total NO2 images on ${date}: ${totalImages}`);

  if (totalImages === 0) {
    console.log("No images found for specified date.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Filter by time (hour of day)
  const afternoon = no2Col.filter(ee.Filter.calendarRange(18, 19, 'hour')); // 2-3pm local
  const evening = no2Col.filter(ee.Filter.calendarRange(21, 22, 'hour')); // 5-6pm local

  const afternoonSize = afternoon.size().getInfo();
  const eveningSize = evening.size().getInfo();

  console.log(`Afternoon (2-3pm local/18-19 UTC) images: ${afternoonSize}`);
  console.log(`Evening (5-6pm local/21-22 UTC) images: ${eveningSize}`);

  if (afternoonSize === 0 || eveningSize === 0) {
    console.log("No images found for one or both time periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create composites with quality masking
  const maskQuality = function(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  };

  const afternoonImg = afternoon.map(maskQuality).mean();
  const eveningImg = evening.map(maskQuality).mean();

  // 4. Calculate mean NO2 and pixel counts
  const afternoonStats = afternoonImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nyc,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const eveningStats = eveningImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nyc,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const afternoonMean = afternoonStats.tropospheric_NO2_column_number_density_mean;
  const afternoonCount = afternoonStats.tropospheric_NO2_column_number_density_count;
  const eveningMean = eveningStats.tropospheric_NO2_column_number_density_mean;
  const eveningCount = eveningStats.tropospheric_NO2_column_number_density_count;

  console.log(`Afternoon NO2: ${afternoonMean?.toExponential(3)} mol/m² (Pixels: ${afternoonCount})`);
  console.log(`Evening NO2: ${eveningMean?.toExponential(3)} mol/m² (Pixels: ${eveningCount})`);

  // 5. Validation & Final Answer
  if (afternoonCount === 0 || eveningCount === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (afternoonMean === null || eveningMean === null || 
      isNaN(afternoonMean) || isNaN(eveningMean)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (afternoonMean > eveningMean) {
    console.log("Afternoon NO2 concentrations were higher than evening.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Afternoon NO2 concentrations were NOT higher than evening.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
